/* Hallmark · shape: Ledger Proof · genre: modern-minimal · theme: Coral (deal: manual) · job: sign up · draw: manual
 * hero: Stage · nav: edge-aligned, a wordmark and one action · footer: a mast · imagery: the product, built as stationery · signature: the statement of what you are owed, the paid row pressed in coral
 * axes: light/grotesk-sans/warm · posture: restrained · contrast: hand-checked · fold: hand-checked (no render run) · v2.0.0 */
/* Hallmark · pre-emit critique: P4 H4 E3 S4 R4 V4 · weakest: E, sloplint could not run in this harness, so every Floor item was walked by hand */
/* Hallmark · answered F4 · two ink buttons, both the one Start free action: the hero sends you to the form, the form submits it */
@import url("./tokens.css");
@import url("./base.css");

/* ---------- shared material ---------- */

.defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.press-shade { flood-color: var(--color-ink); flood-opacity: 0.45; }

.desk {
  background-color: var(--color-desk);
  background-image: radial-gradient(90% 120% at 0% 30%, var(--color-cotton), transparent 62%), var(--tex-desk);
}
.stock {
  background-color: var(--color-cotton);
  background-image: linear-gradient(100deg, var(--color-cotton), transparent 45%), var(--tex-cotton);
  color: var(--color-print);
  box-shadow: var(--edge-stock), var(--cast-stock);
}
.sheet { border-radius: var(--radius-sheet); box-shadow: var(--edge-stock), var(--cast-sheet); }
.card { border-radius: var(--radius-stock); }

.fig { font-family: var(--font-outlier); font-variant-numeric: tabular-nums; font-weight: 400; letter-spacing: 0; }

.pressed {
  display: inline-block;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: var(--text-xl);
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--color-paid);
  filter: url(#press);
  transform: rotate(-6deg);
}

.skip { position: absolute; left: var(--space-md); top: calc(-1 * var(--space-3xl)); z-index: var(--z-toast); padding: var(--space-xs) var(--space-md); background: var(--color-ink); color: var(--color-paper); border-radius: var(--radius-input); }
.skip:focus-visible { top: var(--space-md); }

/* ---------- controls ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 var(--space-lg);
  border: 0;
  border-radius: var(--radius-stock);
  font: 500 var(--text-md)/1 var(--font-body);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition: transform var(--dur-micro) var(--ease-out), box-shadow var(--dur-short) var(--ease-out);
}
.btn--card {
  background-color: var(--color-cotton);
  background-image: var(--tex-cotton);
  color: var(--color-print);
  text-shadow: var(--text-press-lit);
  box-shadow: var(--edge-stock), var(--cast-stock);
}
.btn--ink {
  background: var(--color-board);
  color: var(--color-board-type);
  text-shadow: var(--text-press-ink);
  box-shadow: var(--cast-stock);
}
.btn:hover { transform: translateY(-1px); box-shadow: var(--edge-stock), var(--cast-stock-lift); }
.btn--ink:hover { box-shadow: var(--cast-stock-lift); }
.btn:active { transform: translateY(1px); box-shadow: var(--edge-stock); }
.btn--ink:active { box-shadow: none; }
.btn:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 3px; }
.btn:disabled, .btn[aria-disabled="true"] { opacity: 0.55; cursor: not-allowed; transform: none; box-shadow: var(--edge-stock); }
.btn[aria-busy="true"] { cursor: progress; }

/* ---------- nav ---------- */

.nav { position: absolute; inset-inline: 0; top: 0; z-index: var(--z-raised); }
.nav__row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-lg); min-height: 72px; }
.wordmark {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: var(--text-xl);
  letter-spacing: -0.035em;
  text-decoration: none;
  color: var(--color-ink);
  border-radius: var(--radius-input);
}
.wordmark:hover { color: var(--color-ink-2); }
.wordmark:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 4px; }
.nav__links { display: flex; align-items: center; gap: var(--space-lg); }
.nav__link {
  font-size: var(--text-md);
  font-weight: 500;
  color: var(--color-ink-2);
  text-decoration: underline;
  text-decoration-color: transparent;
  transition: text-decoration-color var(--dur-short) var(--ease-out);
}
.nav__link:hover { color: var(--color-ink); text-decoration-color: var(--color-accent-2); }
.nav__link:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 4px; border-radius: var(--radius-input); }

/* ---------- hero ---------- */

.hero {
  min-height: 100dvh;
  display: grid;
  align-items: center;
  padding-block: var(--space-3xl) var(--space-2xl);
}
.hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 6fr) minmax(0, 6fr);
  gap: var(--space-2xl);
  align-items: center;
}
.hero h1 {
  font-size: clamp(2.75rem, 3.6vw + 1rem, 4.75rem);
  line-height: 1.02;
  max-width: 14ch;
}
.hero .lead { margin-top: var(--space-lg); max-width: 34ch; color: var(--color-ink-2); }
.hero__actions { margin-top: var(--space-xl); display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-md) var(--space-lg); }
.terms { font-size: var(--text-sm); color: var(--color-muted); max-width: 28ch; }

.hero__desk {
  margin: 0;
  position: relative;
  display: grid;
  justify-items: center;
  align-content: center;
  min-height: 540px;
  --rest-card: translate(var(--space-xl), 0) rotate(2.5deg);
}

.statement {
  width: min(100%, 31rem);
  padding: var(--space-xl);
  transform: rotate(-1.5deg);
}
.statement__head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--space-md); }
.statement__label { font-size: var(--text-sm); font-weight: 500; color: var(--color-muted); }
.statement__date { font-size: var(--text-sm); color: var(--color-muted); }
.statement__total {
  margin-top: var(--space-xs);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(2.5rem, 2.6vw + 1rem, 3.5rem);
  line-height: 1;
  letter-spacing: -0.045em;
  color: var(--color-print);
}
.statement__rows { width: 100%; margin-top: var(--space-lg); border-collapse: collapse; }
.statement__rows th,
.statement__rows td { padding: var(--space-sm) 0; border-top: 1px solid var(--color-rule); text-align: left; vertical-align: middle; }
.statement__rows th { font-weight: 500; }
.statement__rows .status { padding-inline: var(--space-sm); font-size: var(--text-sm); color: var(--color-muted); }
.statement__rows .status--late { color: var(--color-print); font-weight: 500; }
.statement__rows .fig { text-align: right; white-space: nowrap; font-size: var(--text-sm); }
.statement__rows .is-settled .fig { color: var(--color-muted); text-decoration: line-through; text-decoration-color: var(--color-rule-2); }

.reminder {
  position: relative;
  z-index: var(--z-raised);
  justify-self: end;
  width: min(82%, 18rem);
  margin-top: calc(-1 * var(--space-2xl));
  padding: var(--space-lg);
  transform: var(--rest-card);
  box-shadow: var(--edge-stock), var(--cast-stock-lift);
}
.reminder__body { font-size: var(--text-md); line-height: 1.4; }
.reminder__by { margin-top: var(--space-sm); font-size: var(--text-sm); color: var(--color-muted); }

/* the job plays once on the desk, from a finished default */
.play-row, .play-card, .play-press {
  transition: opacity var(--dur-long) var(--ease-out), transform var(--dur-long) var(--ease-out);
}
.play-row { transition-delay: calc(var(--dur-short) + var(--i, 0) * 90ms); }
.play-card { transition-duration: 700ms; transition-delay: 1100ms; }
.play-press { transition: opacity var(--dur-micro) var(--ease-out) 2000ms, transform var(--dur-short) var(--ease-in) 2000ms; }
.js [data-play]:not(.is-played) .play-row { opacity: 0; transform: translateY(var(--space-xs)); }
.js [data-play]:not(.is-played) .play-card { opacity: 0; transform: translate(var(--space-2xl), var(--space-xl)) rotate(8deg); }
.js [data-play]:not(.is-played) .play-press { opacity: 0; transform: scale(1.7) rotate(-6deg); }
@media (prefers-reduced-motion: reduce) {
  .play-row, .play-card, .play-press { transition: none; }
  .js [data-play]:not(.is-played) .play-row { opacity: 1; transform: none; }
  .js [data-play]:not(.is-played) .play-card { opacity: 1; transform: var(--rest-card); }
  .js [data-play]:not(.is-played) .play-press { opacity: 1; transform: rotate(-6deg); }
}

/* ---------- the chase ---------- */

.chase { padding-block: var(--section-gap) var(--section-gap-s); }
.head-split {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: var(--space-md) var(--gap-columns);
  align-items: end;
  margin-bottom: var(--space-2xl);
}
.head-split .lead { color: var(--color-ink-2); }

.chase__steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2xl) var(--gap-columns);
}
.chase__step { display: grid; grid-template-rows: auto auto 1fr; gap: var(--space-sm); }
.chase__step h3 { padding-top: var(--space-md); border-top: 1px solid var(--color-rule-2); }
.chase__step p { color: var(--color-ink-2); max-width: 30ch; }
.chase__piece {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: 300px;
  padding-bottom: var(--space-lg);
  margin-bottom: var(--space-sm);
}

.mini {
  width: min(100%, 13.5rem);
  aspect-ratio: 4 / 5;
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-2xs);
  font-size: var(--text-sm);
}
.mini__title { font-weight: 600; font-size: var(--text-md); margin-bottom: var(--space-xs); }
.mini__line { color: var(--color-muted); }
.mini__fig { margin-top: auto; padding-top: var(--space-sm); border-top: 1px solid var(--color-print); text-align: right; }
.mini__stamp { margin-top: auto; text-align: center; }
.mini__stamp .pressed { font-size: var(--text-2xl); }
.chase__step:nth-child(1) .mini { transform: rotate(-1.5deg); }
.chase__step:nth-child(4) .mini { transform: rotate(1deg); }

.note {
  width: min(100%, 15rem);
  padding: var(--space-lg);
  font-size: var(--text-md);
  line-height: 1.4;
  transform: rotate(1.5deg);
}
.note--tucked { transform: rotate(-2deg) translateY(calc(-1 * var(--space-lg))); }

/* ---------- clients ---------- */

.clients { padding-block: var(--section-gap-s) var(--section-gap); }
.clients__grid {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  gap: var(--space-3xl);
  align-items: start;
}
.clients__side .lead { margin-top: var(--space-lg); color: var(--color-ink-2); }

.index { display: grid; gap: var(--space-sm); margin-top: var(--space-xl); max-width: 26rem; }
.index__card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
  min-height: 64px;
  padding: var(--space-md) var(--space-lg);
  border: 0;
  border-radius: var(--radius-sheet);
  background-color: var(--color-cotton);
  background-image: linear-gradient(100deg, var(--color-cotton), transparent 45%), var(--tex-cotton);
  color: var(--color-muted);
  text-align: left;
  cursor: pointer;
  box-shadow: var(--edge-stock), var(--cast-stock);
  transition: transform var(--dur-short) var(--ease-out), box-shadow var(--dur-short) var(--ease-out), color var(--dur-micro) var(--ease-out);
}
.index__card:nth-child(2) { margin-left: var(--space-sm); }
.index__card:nth-child(3) { margin-left: var(--space-lg); }
.index__name { font-weight: 500; }
.index__owed { font-size: var(--text-sm); }
.index__card:hover { color: var(--color-print); transform: translateX(var(--space-2xs)); }
.index__card[aria-selected="true"] {
  color: var(--color-print);
  transform: translateX(var(--space-lg));
  box-shadow: var(--edge-stock), var(--cast-stock-lift);
}
.index__card[aria-selected="true"] .index__name { font-weight: 600; }
.index__card:active { transform: translateX(var(--space-lg)) translateY(1px); }
.index__card:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 3px; }
.index__card:disabled { opacity: 0.55; cursor: not-allowed; }

.records { display: grid; gap: var(--space-xl); }
.record { padding: var(--space-xl); min-height: 380px; }
.record:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 4px; }
.record__head { display: flex; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: var(--space-xs) var(--space-lg); padding-bottom: var(--space-lg); border-bottom: 1px solid var(--color-print); }
.record__owed { color: var(--color-muted); }
.record__owed .fig { color: var(--color-print); font-size: var(--text-lg); }

.ledger { width: 100%; border-collapse: collapse; }
.ledger th, .ledger td { padding: var(--space-md) var(--space-sm) var(--space-md) 0; border-bottom: 1px solid var(--color-rule); text-align: left; vertical-align: middle; }
.ledger thead th { padding-block: var(--space-md) var(--space-sm); font-size: var(--text-sm); font-weight: 500; color: var(--color-muted); white-space: nowrap; }
.ledger tbody th { font-weight: 400; }
.ledger td { color: var(--color-ink-2); }
.ledger .r { text-align: right; padding-right: 0; white-space: nowrap; }
.ledger td.fig, .ledger th.fig { font-size: var(--text-sm); color: var(--color-print); }
.tag { display: inline-block; padding: var(--space-3xs) var(--space-xs); border: 1px solid var(--color-print); border-radius: var(--radius-pill); font-size: var(--text-sm); line-height: 1.3; color: var(--color-print); }

/* ---------- the statement ---------- */

.say { padding-block: var(--section-gap-s) var(--section-gap); border-top: 1px solid var(--color-rule); }
.say__line {
  max-width: 24ch;
  font-family: var(--font-display);
  font-weight: 600;
  font-size: var(--text-display-s);
  line-height: 1.08;
  letter-spacing: var(--tracking-display);
  text-wrap: balance;
  overflow-wrap: break-word;
  min-width: 0;
}

/* ---------- the board ---------- */

.board { background: var(--color-board); color: var(--color-board-type); padding-block: var(--section-gap-s); }
.board__grid {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: var(--space-3xl);
  align-items: center;
}
.board h2 { color: var(--color-board-type); max-width: 16ch; }
.board__figure { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-xs) var(--space-md); margin-top: var(--space-xl); }
.board__zero {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(7rem, 12vw + 1rem, 13rem);
  line-height: 0.85;
  letter-spacing: -0.05em;
}
.board__unit { font-size: var(--text-title); font-weight: 500; color: var(--color-board-muted); }

.plans { margin: var(--space-xl) 0 0; }
.plans__row {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 3fr) minmax(0, 5fr);
  gap: var(--space-md);
  align-items: baseline;
  padding-block: var(--space-md);
  border-top: 1px solid var(--color-board-rule);
}
.plans__row:last-child { border-bottom: 1px solid var(--color-board-rule); }
.plans dt { font-weight: 600; font-size: var(--text-lg); }
.plans dd { margin: 0; color: var(--color-board-muted); }
.plans .plans__price { color: var(--color-board-type); font-weight: 500; }

.signup {
  display: grid;
  gap: var(--space-sm);
  padding: var(--space-xl);
  box-shadow: var(--edge-stock), var(--cast-deep);
}
.signup h3 { margin-bottom: var(--space-sm); }
.signup__label { font-size: var(--text-sm); font-weight: 500; color: var(--color-ink-2); }
.signup input {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 0 var(--space-md);
  border: 1px solid var(--color-muted);
  border-radius: var(--radius-input);
  background: var(--color-cotton);
  color: var(--color-print);
  font-size: var(--text-md);
  outline: 2px solid transparent;
  outline-offset: -3px;
}
.signup input:hover { border-color: var(--color-ink-2); }
.signup input:focus-visible { outline-color: var(--color-focus); }
.signup input[aria-invalid] { border-color: var(--color-error); }
.signup input:disabled { opacity: 0.55; cursor: not-allowed; }
.signup__btn { width: 100%; margin-top: var(--space-xs); }
.signup__help { min-height: 1lh; font-size: var(--text-sm); color: var(--color-muted); }

/* ---------- footer ---------- */

.foot { padding-block: var(--space-3xl) var(--space-xl); }
.foot__mast {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(4.5rem, 13vw, 12rem);
  line-height: 0.9;
  letter-spacing: -0.055em;
  color: var(--color-ink);
}
.foot__row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-md) var(--space-xl);
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--color-rule-2);
}
.foot__links { display: flex; flex-wrap: wrap; gap: var(--space-sm) var(--space-lg); }
.foot__links a {
  white-space: nowrap;
  text-decoration: underline;
  text-decoration-color: transparent;
  transition: text-decoration-color var(--dur-short) var(--ease-out);
}
.foot__links a:hover { text-decoration-color: var(--color-accent-2); }
.foot__links a:focus-visible { outline: 2px solid var(--color-focus); outline-offset: 3px; border-radius: var(--radius-input); }
.foot__legal { font-size: var(--text-sm); color: var(--color-muted); }

/* ---------- responsive ---------- */

@media (max-width: 60rem) {
  .hero { min-height: 0; padding-block: var(--space-3xl) var(--space-2xl); }
  .hero__grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-xl); }
  .hero__desk { min-height: 0; padding-block: var(--space-lg); }
  .head-split { grid-template-columns: minmax(0, 1fr); }
  .chase__steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .clients__grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-2xl); }
  .board__grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-2xl); }
}

@media (max-width: 40rem) {
  .nav__links { gap: var(--space-md); }
  .hero__desk { --rest-card: translate(var(--space-xs), 0) rotate(2deg); }
  .statement { padding: var(--space-lg); }
  .statement__rows th { font-size: var(--text-sm); }
  .statement__rows .status { padding-inline: var(--space-xs); }
  .reminder { width: min(88%, 17rem); }
  .chase__steps { gap: var(--space-xl) var(--space-md); }
  .chase__piece { height: 220px; padding-bottom: var(--space-md); }
  .mini { padding: var(--space-md); font-size: var(--text-xs); }
  .mini__title { font-size: var(--text-sm); }
  .mini__stamp .pressed { font-size: var(--text-xl); }
  .note { padding: var(--space-md); font-size: var(--text-sm); }
  .chase__step h3 { font-size: var(--text-lg); }
  .index__card[aria-selected="true"] { transform: translateX(var(--space-sm)); }
  .index__card:active { transform: translateX(var(--space-sm)) translateY(1px); }
  .index__card:nth-child(2) { margin-left: var(--space-xs); }
  .index__card:nth-child(3) { margin-left: var(--space-md); }
  .record { padding: var(--space-lg); min-height: 0; }
  .ledger .due { display: none; }
  .plans__row { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .plans__row dd:last-child { grid-column: 1 / -1; }
  .signup { padding: var(--space-lg); }
}

