.hero .lead { margin-top: var(--space-lg); max-width: 34ch; color: var(--color-ink-2); }
.hero__actions { margin-top: var(--space-xl); display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-md) var(--space-lg); }
.terms { font-size: var(--text-sm); color: var(--color-muted); max-width: 28ch; }

.hero__desk {
  margin: 0;
  position: relative;
  display: grid;
  justify-items: center;
  align-content: center;
  min-height: 540px;
  --rest-card: translate(var(--space-xl), 0) rotate(2.5deg);
}

.statement {
  width: min(100%, 31rem);
  padding: var(--space-xl);
  transform: rotate(-1.5deg);
}
.statement__head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--space-md); }
.statement__label { font-size: var(--text-sm); font-weight: 500; color: var(--color-muted); }
.statement__date { font-size: var(--text-sm); color: var(--color-muted); }
.statement__total {
  margin-top: var(--space-xs);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(2.5rem, 2.6vw + 1rem, 3.5rem);
  line-height: 1;
  letter-spacing: -0.045em;
  color: var(--color-print);
}
.statement__rows { width: 100%; margin-top: var(--space-lg); border-collapse: collapse; }
.statement__rows th,
.statement__rows td { padding: var(--space-sm) 0; border-top: 1px solid var(--color-rule); text-align: left; vertical-align: middle; }
.statement__rows th { font-weight: 500; }
.statement__rows .status { padding-inline: var(--space-sm); font-size: var(--text-sm); color: var(--color-muted); }
.statement__rows .status--late { color: var(--color-print); font-weight: 500; }
.statement__rows .fig { text-align: right; white-space: nowrap; font-size: var(--text-sm); }
.statement__rows .is-settled .fig { color: var(--color-muted); text-decoration: line-through; text-decoration-color: var(--color-rule-2); }

.reminder {
  position: relative;
  z-index: var(--z-raised);
  justify-self: end;
  width: min(82%, 18rem);
  margin-top: calc(-1 * var(--space-2xl));
  padding: var(--space-lg);
  transform: var(--rest-card);
  box-shadow: var(--edge-stock), var(--cast-stock-lift);
}
.reminder__body { font-size: var(--text-md); line-height: 1.4; }
.reminder__by { margin-top: var(--space-sm); font-size: var(--text-sm); color: var(--color-muted); }

/* the job plays once on the desk, from a finished default */
.play-row, .play-card, .play-press {
  transition: opacity var(--dur-long) var(--ease-out), transform var(--dur-long) var(--ease-out);
}
.play-row { transition-delay: calc(var(--dur-short) + var(--i, 0) * 90ms); }
.play-card { transition-duration: 700ms; transition-delay: 1100ms; }
.play-press { transition: opacity var(--dur-micro) var(--ease-out) 2000ms, transform var(--dur-short) var(--ease-in) 2000ms; }
.js [data-play]:not(.is-played) .play-row { opacity: 0; transform: translateY(var(--space-xs)); }
.js [data-play]:not(.is-played) .play-card { opacity: 0; transform: translate(var(--space-2xl), var(--space-xl)) rotate(8deg); }
.js [data-play]:not(.is-played) .play-press { opacity: 0; transform: scale(1.7) rotate(-6deg); }
@media (prefers-reduced-motion: reduce) {
  .play-row, .play-card, .play-press { transition: none; }
  .js [data-play]:not(.is-played) .play-row { opacity: 1; transform: none; }
  .js [data-play]:not(.is-played) .play-card { opacity: 1; transform: var(--rest-card); }
  .js [data-play]:not(.is-played) .play-press { opacity: 1; transform: rotate(-6deg); }
}

/* ---------- the chase ---------- */

.chase { padding-block: var(--section-gap) var(--section-gap-s); }
.head-split {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: var(--space-md) var(--gap-columns);
  align-items: end;
  margin-bottom: var(--space-2xl);
}
.head-split .lead { color: var(--color-ink-2); }

.chase__steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2xl) var(--gap-columns);
}
.chase__step { display: grid; grid-template-rows: auto auto 1fr; gap: var(--space-sm); }
