.ledger { width: 100%; border-collapse: collapse; }
.ledger th, .ledger td { padding: var(--space-md) var(--space-sm) var(--space-md) 0; border-bottom: 1px solid var(--color-rule); text-align: left; vertical-align: middle; }
.ledger thead th { padding-block: var(--space-md) var(--space-sm); font-size: var(--text-sm); font-weight: 500; color: var(--color-muted); white-space: nowrap; }
